import { daysOverdue } from "./loans.js";

const CENTS_PER_DAY = 25;

// Fine in cents: 25 per day overdue, capped at the replacement cost; children are never fined.
export function fineFor({ dueDate, returnedDate, replacementCents, card }) {
  if (card === "child") return 0;
  const fine = daysOverdue(dueDate, returnedDate) * CENTS_PER_DAY;
  return Math.min(fine, replacementCents);
}
