import { billedMinutes } from "./meter.js";

const FREE_MINUTES = 15;
const CENTS_PER_MINUTE = 5;
const DAILY_CAP_CENTS = 2400;

// Cents charged for one car's sessions in a day, each { startMs, endMs }.
export function dailyCharge(sessions) {
  let cents = 0;
  for (const { startMs, endMs } of sessions) {
    cents += Math.max(0, billedMinutes(startMs, endMs) - FREE_MINUTES) * CENTS_PER_MINUTE;
  }
  return Math.min(cents, DAILY_CAP_CENTS);
}
EOF
