import { average } from "./grades.js";

// A letter grade: A from 90, B from 80, C from 70, otherwise F (no D).
// With four or more scores, the single lowest is dropped before averaging.
export function letterGrade(scores) {
  const counted = scores.filter((s) => s != null);
  const used = counted.length >= 4 ? [...counted].sort((a, b) => a - b).slice(1) : counted;
  const avg = average(used);
  if (avg >= 90) return "A";
  if (avg >= 80) return "B";
  if (avg >= 70) return "C";
  return "F";
}
EOF
